-- =====================================================================
--  FINANCIERA - Íconos en colores del menú (como gestion_sindicato)
--  Correr DESPUÉS de financiera_seguridad.sql. El ALTER va una sola vez, los
--  UPDATE se pueden volver a correr solos.
--
--  Los íconos son los de gestion_sindicato (sql/menu_iconos_color_20261111.sql):
--  Fluent UI System Color Icons (MIT), 18 x 18, uno por opción en todos los
--  niveles. Pintan con degradados por id, y url(#id) apunta al PRIMER elemento
--  con ese id de la página: los id van renombrados f<id de menú>g<n>, y la app
--  los vuelve a renombrar cada vez que dibuja uno (svg_unico en layout.php),
--  porque el mismo ícono puede salir dos veces en una página.
--
--  menu.icono (el nombre de un ícono de trazo de iconos.php) queda como
--  respaldo: se usa si una opción no tiene icono_svg.
-- =====================================================================

SET NAMES utf8mb4;

ALTER TABLE menu ADD COLUMN icono_svg TEXT NULL AFTER icono;

